import { type MatrixHttpApi, Method } from "../../http-api/index.ts";
import type { IHttpOpts } from "../../http-api/index.ts";
import type { IKeyValueStore } from "../../store/KeyValueStore.ts";
import type { MatrixEvent } from "../../models/event.ts";
import { logger } from "../../logger.ts";

export interface SyncManagerEvents {
    sync: { nextBatch: string };
    event: MatrixEvent;
    error: Error;
    stateChange: string;
}

export interface SyncManagerOptions {
    initialSyncLimit?: number;
    filter?: string | Record<string, unknown>;
}

export class SyncManager {
    private syncToken: string | null = null;
    private isSyncing = false;
    private syncTimeout: number = 30000;
    private syncInterval: ReturnType<typeof setInterval> | null = null;

    public constructor(
        private http: MatrixHttpApi<IHttpOpts>,
        private store: IKeyValueStore,
        private options: SyncManagerOptions = {},
    ) {
        this.loadSyncToken();
    }

    public async start(): Promise<void> {
        if (this.isSyncing) {
            logger.warn("SyncManager is already running");
            return;
        }

        this.isSyncing = true;
        await this.sync();

        this.syncInterval = setInterval(() => this.sync(), this.syncTimeout);
        logger.info("SyncManager started");
    }

    public async stop(): Promise<void> {
        if (!this.isSyncing) {
            return;
        }

        this.isSyncing = false;

        if (this.syncInterval !== null) {
            clearInterval(this.syncInterval);
            this.syncInterval = null;
        }

        logger.info("SyncManager stopped");
    }

    public async sync(): Promise<void> {
        if (!this.isSyncing) {
            return;
        }

        try {
            const params: Record<string, string | number | undefined> = {
                since: this.syncToken ?? undefined,
                timeout: this.syncTimeout,
            };

            if (typeof this.options.filter === "string") {
                params.filter = this.options.filter;
            }

            const response = await this.http.authedRequest<{ next_batch: string }>(Method.Get, "/sync", params);

            this.syncToken = response.next_batch;
            await this.saveSyncToken();
        } catch (error) {
            logger.error("Sync failed:", error);
            throw error;
        }
    }

    public getSyncToken(): string | null {
        return this.syncToken;
    }

    public isRunning(): boolean {
        return this.isSyncing;
    }

    public setSyncToken(token: string): void {
        this.syncToken = token;
        this.saveSyncToken();
    }

    public setSyncTimeout(timeout: number): void {
        this.syncTimeout = timeout;
    }

    public async setFilter(filter: string | Record<string, unknown>): Promise<void> {
        this.options.filter = filter;

        if (typeof filter === "object") {
            const response = await this.http.authedRequest<{ filter_id: string }>(
                Method.Post,
                "/user/filter",
                undefined,
                filter,
            );
            this.options.filter = response.filter_id;
        }
    }

    private async loadSyncToken(): Promise<void> {
        this.syncToken = await this.store.getItem<string>("sync_token");
    }

    private async saveSyncToken(): Promise<void> {
        if (this.syncToken) {
            await this.store.setItem("sync_token", this.syncToken);
        }
    }
}
